<template>
  <section class="hotel-assignment">
    <h2>Заселение в отель</h2>

    <div class="controls">
      <button
        @click="loadHotelRooms"
        :disabled="
          hotelStore.loading || (hotelStore.hasRooms && !hotelStore.error)
        "
      >
        {{ buttonText }}
      </button>

      <div v-if="hotelStore.hasRooms && !hotelStore.loading" class="summary">
        Номеров: <strong>{{ hotelStore.totalRooms }}</strong> мест:
        <strong>{{ hotelStore.totalBeds }}</strong>
        <span v-if="hotelStore.occupiedBeds > 0">
          (заполнено: {{ hotelStore.occupiedBeds }})
        </span>
      </div>
    </div>

    <div v-if="hotelStore.loading" class="status loading">
      Загружаем структуру номеров...
    </div>

    <div v-if="hotelStore.error" class="status error">
      {{ hotelStore.error }}
      <button @click="loadHotelRooms" class="retry">Повторить</button>
    </div>

    <div v-if="hotelStore.hasRooms && !hotelStore.loading" class="rooms-grid">
      <div
        v-for="roomKey in hotelStore.sortedRoomKeys"
        :key="roomKey"
        class="room-card"
      >
        <h3>
          {{ roomKey }}
          <small>({{ getCapacity(roomKey) }}-местный)</small>
        </h3>

        <div class="beds">
          <div
            v-for="(person, bedKey) in hotelStore.rooms[roomKey]"
            :key="bedKey"
            class="bed-slot"
          >
            <div class="bed-label">Кровать {{ bedKey }}</div>
            <div class="person-data">
              <div>
                ФИО: <span>{{ person.FIO || "—" }}</span>
              </div>
              <div>
                Паспорт: <span>{{ person.PASS || "—" }}</span>
              </div>
              <div>
                Телефон: <span>{{ person.PHONE || "—" }}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div
      v-if="!hotelStore.hasRooms && !hotelStore.loading && !hotelStore.error"
      class="empty"
    >
      Нажмите кнопку выше, чтобы загрузить список номеров
    </div>
  </section>
</template>

<script>
import { useAuthStore } from "@/stores/auth";
import { useHotelStore } from "@/stores/hotel";

export default {
  name: "HotelAssignment",

  data() {
    return {
      // можно добавить локальные данные, если нужно
    };
  },

  computed: {
    authStore() {
      return useAuthStore();
    },

    hotelStore() {
      return useHotelStore();
    },

    buttonText() {
      if (this.hotelStore.loading) return "Загрузка...";
      if (this.hotelStore.hasRooms && !this.hotelStore.error)
        return "Номера загружены";
      return "Загрузить номера отеля";
    },
  },

  methods: {
    getCapacity(roomKey) {
      return roomKey.split(".")[0];
    },

    async loadHotelRooms() {
      if (this.hotelStore.loading) return;

      this.hotelStore.startLoading();

      try {
        const payload = {
          token: this.authStore.token, // для авторизации на сервере

          singles: this.authStore.singleRoomsCount,
          doubles: this.authStore.doubleRoomsCount,
          triples: this.authStore.tripleRoomsCount,
          quads: this.authStore.quadRoomsCount,
        };

        const response = await fetch("https://dancerus.ru/api/get_rooms.php", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload),
        });

        if (!response.ok) {
          throw new Error(`Сервер ответил ${response.status}`);
        }

        const data = await response.json();
        this.hotelStore.setRooms(data); // ← здесь ожидается структура комнат (если сервер её возвращает)
      } catch (err) {
        this.hotelStore.setError(`Не удалось загрузить номера: ${err.message}`);
        console.error(err);
      } finally {
        this.hotelStore.finishLoading();
      }
    },
  },

  // Опционально: можно загрузить автоматически при монтировании
  // mounted() {
  //   if (!this.hotelStore.hasRooms) {
  //     this.loadHotelRooms()
  //   }
  // }
};
</script>

