// src/stores/hotel.js
import { defineStore } from 'pinia'

export const useHotelStore = defineStore('hotel', {
  state: () => ({
    rooms: {},           // { "1.1": { "1": {FIO:"", PASS:"", PHONE:""} }, "2.1": {...}, ... }
    loading: false,
    error: null,
    lastLoadedAt: null
  }),

  getters: {
    hasRooms: state => Object.keys(state.rooms).length > 0,

    sortedRoomKeys: state => {
      return Object.keys(state.rooms).sort((a, b) => {
        const [typeA, numA] = a.split('.').map(Number)
        const [typeB, numB] = b.split('.').map(Number)
        if (typeA !== typeB) return typeA - typeB
        return numA - numB
      })
    },

    totalRooms: state => Object.keys(state.rooms).length,

    totalBeds: state => {
      let count = 0
      Object.values(state.rooms).forEach(beds => {
        count += Object.keys(beds).length
      })
      return count
    },

    occupiedBeds: state => {
      let count = 0
      Object.values(state.rooms).forEach(beds => {
        Object.values(beds).forEach(person => {
          if (person.FIO?.trim()) count++
        })
      })
      return count
    }
  },

  actions: {
    setRooms(data) {
      this.rooms = { ...data }
      this.lastLoadedAt = new Date()
      this.error = null
    },

    startLoading() {
      this.loading = true
      this.error = null
    },

    setError(message) {
      this.error = message
      this.loading = false
    },

    finishLoading() {
      this.loading = false
    },

    clear() {
      this.rooms = {}
      this.error = null
      this.lastLoadedAt = null
      this.loading = false
    },

    // Пример будущего метода — обновление одного человека
    updatePerson(roomKey, bedKey, updates) {
      if (this.rooms[roomKey]?.[bedKey]) {
        this.rooms[roomKey][bedKey] = {
          ...this.rooms[roomKey][bedKey],
          ...updates
        }
      }
    }
  }
})